// spec: .qa/e2e/specs/moderation-menu.md 1.4 · seed: tests/seed.user4.moderation.spec.ts · тикеты #714b7a (AC 1–3, 5; Figma 895:11284), #4d3a4c (AC 3, 6; список 944:17264)
// @data: user4 блокирует демо-автора «רוני» (сид, не реальный пользователь) и снимает блок через «משתמשים חסומים».
// В finally — запасное снятие блока (DELETE blocks).
import { test, expect } from '@playwright/test';
import { openFeed } from '../post-create/post-helpers';
import { DEMO_POST, tapIn, appApi, closeApp, iphoneAs, unblock } from './mod-helpers';
import type { Api } from '../_shared/api';

test.describe('רכיב תפריט דיווח וחסימה — чужой контент', () => {
  test('Чужой пост: меню «דיווח על הפוסט» + «חסימת רוני» без удаления; «לחסום את רוני?» → посты скрыты; «ביטול חסימה» в «משתמשים חסומים» возвращает @iphone @data (#714b7a #4d3a4c)', async ({ browser }) => {
    test.setTimeout(120_000);
    const page = await iphoneAs(browser, 'user4');
    let api: Api | undefined;
    let blocked = false;
    try {
      api = await appApi(page);
      await unblock(api, DEMO_POST.authorId); // чистое начало, если прошлый прогон оборвался
      await openFeed(page);
      const post = page.getByText(DEMO_POST.text);
      await expect(post).toBeVisible();
      const card = page.locator('div').filter({ has: post }).filter({ has: page.getByRole('button', { name: 'פעולות על הפוסט' }) }).last();

      // Меню чужого поста: жалоба и блок, без удаления/редактирования (AC 1–3)
      await tapIn(page, card.getByRole('button', { name: 'פעולות על הפוסט' }));
      const menu = page.getByRole('dialog').filter({ hasText: 'פעולות על הפוסט' });
      await expect(menu.getByRole('button', { name: /דיווח על הפוסט/ })).toBeVisible();
      await expect(menu.getByRole('button', { name: new RegExp(`חסימת ${DEMO_POST.author}`) })).toBeVisible();
      await expect(menu.getByRole('button', { name: /מחיקת/ })).toHaveCount(0);
      await expect(menu.getByRole('button', { name: /עריכת/ })).toHaveCount(0);

      // Окно блока «לחסום את רוני?» (895:11284): «ביטול» ничего не меняет
      await tapIn(page, menu.getByRole('button', { name: new RegExp(`חסימת ${DEMO_POST.author}`) }));
      const confirm = page.getByRole('dialog').filter({ hasText: `לחסום את ${DEMO_POST.author}?` });
      await expect(confirm).toContainText('אפשר לבטל בהגדרות › משתמשים חסומים');
      await tapIn(page, confirm.getByRole('button', { name: 'ביטול', exact: true }));
      await expect(confirm).toHaveCount(0);
      await expect(post).toBeVisible();

      // Блок: POST blocks 201, посты автора пропали из ленты
      await tapIn(page, card.getByRole('button', { name: 'פעולות על הפוסט' }));
      await tapIn(page, page.getByRole('button', { name: new RegExp(`חסימת ${DEMO_POST.author}`) }));
      const blockRes = page.waitForResponse((r) => r.request().method() === 'POST' && /\/rest\/v1\/blocks(\?|$)/.test(r.url()));
      await tapIn(page, page.getByRole('dialog').filter({ hasText: `לחסום את ${DEMO_POST.author}?` }).getByRole('button', { name: 'לחסום', exact: true }));
      expect((await blockRes).status(), 'POST blocks').toBe(201);
      blocked = true;
      await expect(post).toHaveCount(0);

      // Список «משתמשים חסומים» → «ביטול חסימה» → подтверждение → список пуст по этому автору, пост снова в ленте
      await page.goto('/blocked-users');
      await expect(page.getByText(new RegExp(`${DEMO_POST.author}\\s*נחסם`))).toBeVisible();
      await tapIn(page, page.getByRole('button', { name: `ביטול חסימה ${DEMO_POST.author}` }));
      const un = page.getByRole('dialog').filter({ hasText: `לבטל את החסימה של ${DEMO_POST.author}?` });
      await expect(un).toBeVisible();
      const unRes = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes('/rest/v1/blocks?'));
      await tapIn(page, un.getByRole('button', { name: 'לבטל חסימה' }));
      expect((await unRes).ok(), 'DELETE blocks').toBeTruthy();
      blocked = false;
      await expect(page.getByRole('button', { name: `ביטול חסימה ${DEMO_POST.author}` })).toHaveCount(0);
      await openFeed(page);
      await expect(page.getByText(DEMO_POST.text)).toBeVisible();
    } finally {
      if (api && blocked) await unblock(api, DEMO_POST.authorId);
      await closeApp(page, 'user4');
    }
  });
});
